const item = $('Get Item Price').item.json;
const promoRaw = $('Get Seller Promotions').item.json;

if (!item || !item.id) {
  return [{ json: { result: 'No se pudo obtener el precio. Verific\u00e1 el ID del producto.' } }];
}

const moneda = item.currency_id || 'ARS';
let precioOriginal = null;
let precioFinal = null;
let descuentoPct = 0;
let tienePromo = false;
let fuentePrecio = 'items';

const promos = Array.isArray(promoRaw) ? promoRaw : (promoRaw && Array.isArray(promoRaw.results) ? promoRaw.results : null);

if (promos && promos.length > 0) {
  const promo = promos.find(p => p.status === 'started' || p.status === 'active') || promos[0];
  if (promo.new_price || promo.price) {
    const promoPrice = promo.new_price || promo.price;
    const promoOriginal = promo.original_price || promo.old_price || item.price;
    if (promoPrice < promoOriginal) {
      precioFinal = `$${promoPrice.toLocaleString('es-AR')}`;
      precioOriginal = `$${promoOriginal.toLocaleString('es-AR')}`;
      descuentoPct = Math.round((1 - promoPrice / promoOriginal) * 100);
      tienePromo = true;
      fuentePrecio = 'seller-promotions';
    }
  }
}

if (!tienePromo) {
  const precio = item.price;

  if (item.sale_price && typeof item.sale_price === 'object' && item.sale_price.amount && item.sale_price.amount < precio) {
    precioOriginal = `$${precio.toLocaleString('es-AR')}`;
    precioFinal = `$${item.sale_price.amount.toLocaleString('es-AR')}`;
    descuentoPct = Math.round((1 - item.sale_price.amount / precio) * 100);
    tienePromo = true;
    fuentePrecio = 'sale_price';
  }
  else if (item.original_price && item.original_price > precio) {
    precioOriginal = `$${item.original_price.toLocaleString('es-AR')}`;
    precioFinal = `$${precio.toLocaleString('es-AR')}`;
    descuentoPct = Math.round((1 - precio / item.original_price) * 100);
    tienePromo = true;
    fuentePrecio = 'original_price';
  }
  else if (item.base_price && item.base_price > precio) {
    precioOriginal = `$${item.base_price.toLocaleString('es-AR')}`;
    precioFinal = `$${precio.toLocaleString('es-AR')}`;
    descuentoPct = Math.round((1 - precio / item.base_price) * 100);
    tienePromo = true;
    fuentePrecio = 'base_price';
  }
  else {
    precioFinal = `$${precio.toLocaleString('es-AR')}`;
  }
}

let result = `\ud83d\udcb0 PRECIO - ${item.title}\n\n`;
result += `Precio actual: ${precioFinal} ${moneda}\n`;
if (tienePromo) {
  result += `Precio original: ${precioOriginal} ${moneda}\n`;
  result += `Descuento: ${descuentoPct}% OFF \ud83d\udd25\n`;
} else {
  result += `Sin descuento activo\n`;
}
result += `Stock: ${item.available_quantity || 'N/A'} unidades\n`;
result += `Link: ${item.permalink || 'N/A'}\n`;
result += `ID: ${item.id}`;

return [{ json: { result } }];
